1	/** Package-owned durable read-barrier invariants. @module @deepseek-ai/dsh-read-barrier/invariant */
2	
3	import type { Context } from '@deepseek-ai/cordis'
4	import type { InvariantFailure, InvariantInstaller } from '@deepseek-ai/dsh-invariants'
5	import type { Session, SessionEvent } from '@deepseek-ai/dsh-session'
6	import type {
7	  ReadBarrierAttestation,
8	  ReadBarrierCapability,
9	  ReadBarrierDenial,
10	  ReadBarrierEnforcementState,
11	  ReadBarrierRole,
12	  ReadBarrierScope,
13	} from './types.ts'
14	import {
15	  ENFORCED_CAPABILITY_SERVICES,
16	  READ_BARRIER_ATTESTATION_VERSION,
17	  READ_BARRIER_DENIED_VERSION,
18	  READ_BARRIER_SCOPE_VERSION,
19	} from './index.ts'
20	
21	const PACKAGE_NAME = '@deepseek-ai/dsh-read-barrier'
22	
23	/** Cordis companion plugin name. */
24	export const name = 'read-barrier-invariant'
25	/** Service required before the companion can reserve package ownership. */
26	export const inject = ['invariants']
27	
28	/** Every seam that can refuse a read. */
29	const CAPABILITIES: readonly ReadBarrierCapability[] = ['fs', 'shell', 'subprocess', 'terminal']
30	
31	/** Every role a session can hold. */
32	const ROLES: readonly ReadBarrierRole[] = ['implementer', 'validator', 'unrestricted']
33	
34	/** Every enforcement decision a capability can record. */
35	const ENFORCEMENT_STATES: readonly ReadBarrierEnforcementState[] = ['denied-at-executor', 'unenforced', 'not-composed']
36	
37	/** Sessions whose census is already recorded, so a second one is caught as a contradiction. */
38	const sessionScope = new WeakMap<object, ReadBarrierScope>()
39	
40	/**
41	 * The barrier root the first refusal in a session named. One composition owns
42	 * one root, so every later refusal in that session must name the same one.
43	 */
44	const sessionRoot = new WeakMap<object, string>()
45	
46	/** Reject a refusal whose payload is not the record this package writes. */
47	function checkPayload(denial: ReadBarrierDenial, seq: number, fail: InvariantFailure): void {
48	  // Widened: the durable log is a boundary, so a version this build does not
49	  // write can still appear here even though the declared type pins one literal.
50	  const version: number = denial.version
51	  if (version !== READ_BARRIER_DENIED_VERSION) {
52	    fail(`session event ${seq} records a read-barrier/denied of unknown version ${JSON.stringify(version)}`)
53	  }
54	  if (!CAPABILITIES.includes(denial.capability)) {
55	    fail(`session event ${seq} records a read-barrier/denied from unknown capability ${JSON.stringify(denial.capability)}`)
56	  }
57	  if (denial.role !== 'implementer') {
58	    fail(`session event ${seq} records a read-barrier/denied for role ${JSON.stringify(denial.role)}; only an implementer is denied a read`)
59	  }
60	}
61	
62	/** Reject a refusal that names a different barrier root than the session's earlier refusals. */
63	function checkConstantRoot(session: object, root: string, seq: number, fail: InvariantFailure): void {
64	  const first = sessionRoot.get(session)
65	  if (first === undefined) {
66	    sessionRoot.set(session, root)
67	    return
68	  }
69	  if (first !== root) {
70	    fail(`session event ${seq} records a read-barrier/denied under root ${JSON.stringify(root)} after ${JSON.stringify(first)}`)
71	  }
72	}
73	
74	/** Reject a census that is not the record this package writes, or a second one in the same session. */
75	function checkScope(session: object, scope: ReadBarrierScope, seq: number, fail: InvariantFailure): void {
76	  // Widened: the durable log is a boundary, so a version this build does not
77	  // write can still appear here even though the declared type pins one literal.
78	  const version: number = scope.version
79	  if (version !== READ_BARRIER_SCOPE_VERSION) {
80	    fail(`session event ${seq} records a read-barrier/scope of unknown version ${JSON.stringify(version)}`)
81	  }
82	  if (!ROLES.includes(scope.role)) {
83	    fail(`session event ${seq} records a read-barrier/scope for unknown role ${JSON.stringify(scope.role)}`)
84	  }
85	  for (const entry of scope.enforcement) {
86	    if (!(entry.capability in ENFORCED_CAPABILITY_SERVICES)) {
87	      fail(`session event ${seq} records read-barrier/scope enforcement for unknown capability ${JSON.stringify(entry.capability)}`)
88	    }
89	    if (!ENFORCEMENT_STATES.includes(entry.state)) {
90	      fail(`session event ${seq} records read-barrier/scope enforcement state ${JSON.stringify(entry.state)} for ${JSON.stringify(entry.capability)}`)
91	    }
92	  }
93	  const first = sessionScope.get(session)
94	  if (first === undefined) {
95	    sessionScope.set(session, scope)
96	    return
97	  }
98	  fail(`session event ${seq} records a second read-barrier/scope; one session composes one census`)
99	}
100	
101	/** Reject an attestation whose payload is not the record this package writes. */
102	function checkAttestation(attestation: ReadBarrierAttestation, seq: number, fail: InvariantFailure): void {
103	  // Widened for the same durable-boundary reason as the census version.
104	  const version: number = attestation.version
105	  if (version !== READ_BARRIER_ATTESTATION_VERSION) {
106	    fail(`session event ${seq} records a read-barrier/attestation of unknown version ${JSON.stringify(version)}`)
107	  }
108	  if (attestation.path === '') {
109	    fail(`session event ${seq} records a read-barrier/attestation with no file path`)
110	  }
111	}
112	
113	/** Validate the package-owned records and ignore unrelated events. */
114	function validateEvent(session: object, event: SessionEvent, fail: InvariantFailure): void {
115	  if (event.type === 'read-barrier/scope') {
116	    checkScope(session, event.data, event.seq, fail)
117	    checkConstantRoot(session, event.data.root, event.seq, fail)
118	    return
119	  }
120	  if (event.type === 'read-barrier/attestation') {
121	    checkAttestation(event.data, event.seq, fail)
122	    return
123	  }
124	  if (event.type !== 'read-barrier/denied') return
125	  checkPayload(event.data, event.seq, fail)
126	  checkConstantRoot(session, event.data.root, event.seq, fail)
127	}
128	
129	/* jscpd:ignore-start -- package companions share replay and dispatch plumbing */
130	/** Install validation for loaded and newly appended refusal records. */
131	const install: InvariantInstaller = Object.assign((ctx: Context, fail: InvariantFailure) => {
132	  for (const session of ctx.sessions.list()) {
133	    for (const event of session.events) validateEvent(session, event, fail)
134	  }
135	  ctx.on('internal/dispatch', (_mode, eventName, args) => {
136	    if (eventName !== 'session/event') return
137	    const [session, event] = args as [Session, SessionEvent]
138	    validateEvent(session, event, fail)
139	  }, { global: true })
140	}, { inject: ['sessions'] })
141	/* jscpd:ignore-end */
142	
143	/**
144	 * Register this package's invariant companion.
145	 * @param ctx - Cordis context carrying the invariant service.
146	 * @returns the installed registration's disposer after setup succeeds.
147	 */
148	export const apply = (ctx: Context): Promise<() => void> =>
149	  Promise.resolve(ctx.invariants.register(PACKAGE_NAME, install))
150

