      type: 'result',
      mountRefusal,
      refusedSessionExists,
      guarded,
      openCall: { isError: openCall.isError },
      openTools: ctx.tools.schemas(open.agent).map(schema => schema.name).sort(),
      implementerTools: ctx.tools.schemas(implementer.agent).map(schema => schema.name).sort(),
